import { createPcmWav, withId3TextFrames } from '../support/pcmWav';

// Minimal synthetic containers that tagging tools write, so the real embedded-metadata reader parses each format.
const u32 = (value: number, littleEndian = false) => { const bytes = Buffer.alloc(4); if (littleEndian) bytes.writeUInt32LE(value); else bytes.writeUInt32BE(value); return bytes; };
const box = (type: string, ...children: Buffer[]) => { const body = Buffer.concat(children), header = Buffer.alloc(8); header.writeUInt32BE(body.length + 8); header.write(type, 4, 'latin1'); return Buffer.concat([header, body]); };
/** fLaC with a 3-second STREAMINFO and a VORBIS_COMMENT block. */
function flacSample(comments: [string, string][]) {
    const block = (type: number, data: Buffer, last: boolean) => { const header = Buffer.alloc(4); header[0] = (last ? 0x80 : 0) | type; header.writeUIntBE(data.length, 1, 3); return Buffer.concat([header, data]); };
    const info = Buffer.alloc(34); info.writeUInt16BE(4096, 0); info.writeUInt16BE(4096, 2);
    // 44.1 kHz, two channels, 16 bits, 132,300 samples.
    info.writeBigUInt64BE((44_100n << 44n) | (1n << 41n) | (15n << 36n) | 132_300n, 10);
    const vendor = Buffer.from('synthetic'), entries = comments.map(([key, value]) => Buffer.from(`${key}=${value}`, 'utf8'));
    return Buffer.concat([Buffer.from('fLaC'), block(0, info, false), block(4, Buffer.concat([u32(vendor.length, true), vendor, u32(entries.length, true), ...entries.flatMap(entry => [u32(entry.length, true), entry])]), true)]);
}
/** ftyp, moov/mvhd and an iTunes ilst with text atoms, disk 2/3, trkn 4/9 and com.apple.iTunes freeform atoms. */
function mp4Sample(texts: Record<string, string>, freeform: Record<string, string>) {
    const data = (type: number, value: Buffer) => box('data', u32(type), u32(0), value);
    const items = [...Object.entries(texts).map(([key, value]) => box(key, data(1, Buffer.from(value, 'utf8')))),
        box('trkn', data(0, Buffer.from([0, 0, 0, 4, 0, 9, 0, 0]))), box('disk', data(0, Buffer.from([0, 0, 0, 2, 0, 3]))),
        ...Object.entries(freeform).map(([name, value]) => box('----', box('mean', u32(0), Buffer.from('com.apple.iTunes')), box('name', u32(0), Buffer.from(name)), data(1, Buffer.from(value, 'utf8'))))];
    const matrix = Buffer.concat([u32(0x10000), u32(0), u32(0), u32(0), u32(0x10000), u32(0), u32(0), u32(0), u32(0x40000000)]);
    const mvhd = box('mvhd', u32(0), u32(0), u32(0), u32(1000), u32(3000), u32(0x10000), Buffer.from([1, 0]), Buffer.alloc(10), matrix, Buffer.alloc(24), u32(2));
    const meta = box('meta', u32(0), box('hdlr', u32(0), u32(0), Buffer.from('mdirappl'), Buffer.alloc(9)), box('ilst', ...items));
    return Buffer.concat([box('ftyp', Buffer.from('M4A '), u32(0), Buffer.from('M4A mp42isom')), box('moov', mvhd, box('udta', meta))]);
}
const read = async (bytes: Buffer, mimeType: string, path: string) => readImportEmbeddedTags(await parseBuffer(Uint8Array.from(bytes), { mimeType, path, size: bytes.length }, { duration: true, skipCovers: true }));
const expectedEvidence = (durationMs: number | null) => ({ version: 2, title: 'Synthetic Title', album: 'Synthetic Album', artists: ['Synthetic Artist'], albumArtists: ['Synthetic Album Artist'], label: 'Synthetic Label', year: 2026,
    discNumber: 2, trackNumber: 4, durationMs, identifiers: { barcode: '4006381333931', catalogNumber: 'SYN-001', isrc: 'USABC2600001', musicBrainzReleaseId: '00000009-0000-4000-8000-0000000000f2' }, flagged: [] });

test('ID3, FLAC and MP4 tags all yield the same version-2 evidence', async () => {
    const wav = withId3TextFrames(createPcmWav(300), { TIT2: 'Synthetic Title', TALB: 'Synthetic Album', TPE1: 'Synthetic Artist', TPE2: 'Synthetic Album Artist', TPUB: 'Synthetic Label', TPOS: '2/3', TRCK: '4/9', TYER: '2026',
        TSRC: 'USABC2600001', 'TXXX:BARCODE': '4006381333931', 'TXXX:CATALOGNUMBER': 'SYN-001', 'TXXX:MusicBrainz Album Id': '00000009-0000-4000-8000-0000000000F2' });
    assert.deepEqual(await read(wav, 'audio/wav', 'synthetic.wav'), expectedEvidence(300));
    const flac = flacSample([['TITLE', 'Synthetic Title'], ['ALBUM', 'Synthetic Album'], ['ARTIST', 'Synthetic Artist'], ['ALBUMARTIST', 'Synthetic Album Artist'], ['LABEL', 'Synthetic Label'], ['DISCNUMBER', '2'],
        ['TRACKNUMBER', '4'], ['DATE', '2026'], ['ISRC', 'US-ABC-26-00001'], ['BARCODE', '4006381333931'], ['CATALOGNUMBER', 'SYN-001'], ['MUSICBRAINZ_ALBUMID', '00000009-0000-4000-8000-0000000000f2']]);
    assert.deepEqual(await read(flac, 'audio/flac', 'synthetic.flac'), expectedEvidence(3000));
    // This MP4 carries no audio track, so its duration is unknown.
    const mp4 = mp4Sample({ '\u00a9nam': 'Synthetic Title', '\u00a9alb': 'Synthetic Album', '\u00a9ART': 'Synthetic Artist', aART: 'Synthetic Album Artist', '\u00a9day': '2026' },
        { LABEL: 'Synthetic Label', BARCODE: '4006381333931', CATALOGNUMBER: 'SYN-001', ISRC: 'USABC2600001', 'MusicBrainz Album Id': '00000009-0000-4000-8000-0000000000f2' });
    assert.deepEqual(await read(mp4, 'audio/mp4', 'synthetic.m4a'), expectedEvidence(null));
});

test('a real tag with control or invisible formatting characters, over a limit or out of format is left out and flagged', async () => {
    const wav = withId3TextFrames(createPcmWav(300), { TIT2: 'Bell\u0007Title', TALB: 'Zero\u200bWidth', TPE1: 'a'.repeat(201), TPUB: '  Synthetic Label  ', TSRC: 'not-an-isrc', 'TXXX:BARCODE': '4006381333932' });
    const tags = await read(wav, 'audio/wav', 'synthetic.wav');
    assert.deepEqual([tags.title, tags.album, tags.artists, tags.label, tags.identifiers.isrc, tags.identifiers.barcode], [null, null, [], 'Synthetic Label', null, null]);
    assert.deepEqual(tags.flagged, [{ field: 'barcode', reason: 'format' }, { field: 'isrc', reason: 'format' }, { field: 'title', reason: 'characters' }, { field: 'album', reason: 'characters' }, { field: 'artists', reason: 'length' }]);
});

test('canonical copy uses one SDK PUT attempt so a late retry cannot recreate a cancelled key', async t => {
    const bytes = Buffer.from('Synthetic bounded audio bytes'); let puts = 0;
    const server = createServer(async (req, res) => {
        assert.equal(req.method, 'PUT'); puts++;
        assert.equal(req.headers['if-none-match'], '*');
        const body: Buffer[] = []; for await (const chunk of req) body.push(Buffer.from(chunk));
        assert.deepEqual(Buffer.concat(body), bytes);
        res.statusCode = 503; res.setHeader('Content-Type', 'application/xml');
        res.end('<Error><Code>ServiceUnavailable</Code><Message>Synthetic retryable response</Message></Error>');
    });
    await new Promise<void>(resolve => server.listen(0, '127.0.0.1', resolve));
    const address = server.address(); assert.ok(address && typeof address !== 'string');
    const shared = getS3(), previousEndpoint = shared.config.endpoint;
    shared.config.endpoint = async () => ({ protocol: 'http:', hostname: '127.0.0.1', port: address.port, path: '/' });
    t.mock.method(shared, 'send', async command => {
        assert.ok(command instanceof GetObjectCommand); assert.equal(command.input.IfMatch, '"source"');
        assert.equal(command.input.VersionId, 'source-version');
        // A replayable byte body makes SDK retry policy observable, independently of stream retry restrictions.
        return { ContentLength: bytes.length, Body: bytes };
    });
    const originalSend = S3Client.prototype.send;
    t.mock.method(S3Client.prototype, 'send', async function(this: S3Client, command: any, options: any) {
        assert.ok(command instanceof PutObjectCommand); assert.equal(await this.config.maxAttempts(), 1);
        return originalSend.call(this, command, options);
    });
    const target: ImportObjectTarget = { bucket: 'synthetic-canonical', key: `audio/${'1'.repeat(24)}/${'2'.repeat(24)}`,
        sha256: createHash('sha256').update(bytes).digest('hex'), byteLength: bytes.length, contentType: 'audio/wav',
        importId: '3'.repeat(24), slotId: randomUUID(), operationId: randomUUID() };
    try {
        await assert.rejects(defaultImportObjectStorage.copy({ ...target, bucket: 'synthetic-private', key: 'imports/source', etag: '"source"', versionId: 'source-version' }, target),
            (error: any) => error.$metadata?.attempts === 1);
        assert.equal(puts, 1);
    } finally {
        shared.config.endpoint = previousEndpoint;
        await new Promise<void>(resolve => server.close(() => resolve()));
    }
});

test('a missing upload settles only after its lease ends and its transfer deadline passes', () => {
    const now = new Date('2026-10-18T12:00:00.000Z'), at = (ms: number) => new Date(now.getTime() + ms);
    const asset = (fields: Partial<ImportAsset>) => ({ updatedAt: at(-1_000), leaseUntil: null, transferDeadline: at(-1), ...fields }) as ImportAsset;
    assert.equal(importUploadSettled(asset({ leaseUntil: at(1) }), now), false, 'an active lease may still PUT');
    assert.equal(importUploadSettled(asset({ transferDeadline: at(1) }), now), false, 'before the transfer deadline');
    assert.equal(importUploadSettled(asset({ leaseUntil: at(-1) }), now), true, 'after an expired lease and the deadline');
    assert.equal(importUploadSettled(asset({ transferDeadline: now }), now), true, 'at the deadline');
    assert.equal(importUploadSettled(asset({ transferDeadline: undefined, updatedAt: at(-ADMIN_IMPORT_LIMITS.uploadSettleMs + 1) }), now), false, 'legacy record inside updatedAt fallback');
    assert.equal(importUploadSettled(asset({ transferDeadline: null, updatedAt: at(-ADMIN_IMPORT_LIMITS.uploadSettleMs) }), now), true, 'legacy record after updatedAt fallback');
});
test('sources stay locked during an active publication or pending cancelled cleanup', () => {
    const media = (publication?: Partial<ImportMedia['publication']>) => ({ assets: [], ...(publication ? { publication } : {}) }) as ImportMedia;
    assert.equal(importSourcesLocked(undefined), false); assert.equal(importSourcesLocked(media()), false);
    for (const state of ['preparing', 'needsAttention', 'complete'] as const) assert.equal(importSourcesLocked(media({ state })), true, state);
    assert.equal(importSourcesLocked(media({ state: 'cancelled', cleanupPending: true })), true);
    assert.equal(importSourcesLocked(media({ state: 'cancelled', cleanupPending: false })), false);
});
